import math

def find_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

solutions = []
x = 2
y_range = range(5, 16)

print("--- Starting Systematic Check for x=2, 5 <= y <= 15 ---")

for y in y_range:
    # The equation is z^3 - (x^2 * y^2) * z^2 + (x^3 + y^3) = 0
    # x=2, so x^2*y^2 = 4*y^2, and x^3+y^3 = 8 + y^3

    constant_term = 8 + y**3

    # Z must be a divisor of constant_term
    divisors = find_divisors(constant_term)

    found_solutions_for_y = []

    for z in divisors:
        # Constraint 1: z >= y
        if z < y:
            continue

        # Constraint 2: Check if z satisfies the cubic equation
        # z^3 - (4*y^2)*z^2 + constant_term = 0

        LHS = z**3 - (4 * y**2) * z**2 + constant_term

        if LHS == 0:
            found_solutions_for_y.append((x, y, z))

    if found_solutions_for_y:
        solutions.extend(found_solutions_for_y)
        print(f"Found solutions for y={y}: {found_solutions_for_y}")

print("\n--- Summary of all found solutions ---")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the specified range.")
